<template>
<section class="storage-page storage-inventory-page">
 <FactoryToolbar :before-change="beforeChange"><el-select v-model="filters.warehouseId" :disabled="!state.factoryId" placeholder="仓库" clearable><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select><el-input v-model="filters.name" :disabled="!state.factoryId" :placeholder="tab==='RAW'?'物料编码 / 名称':'产品名称'" @keyup.enter="search"/><el-input v-model="filters.specification" :disabled="!state.factoryId" placeholder="规格型号"/><el-select v-model="filters.customerId" :disabled="!state.factoryId" placeholder="客户料权" clearable><el-option label="工厂自有" value="0"/><el-option v-for="c in customers" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-button class="list-action" :disabled="!state.factoryId" @click="search">查询</el-button><el-button class="list-action list-action--neutral" @click="reset">重置</el-button><el-button v-if="can('metal:inventory:export')" class="list-action" :disabled="!state.factoryId||loading" @click="exportRows">导出</el-button><el-button v-if="can('metal:material-debt:list')" @click="debtsOpen=true">借还料账</el-button><el-button v-if="can('metal:inventory:adjust')" :disabled="!state.factoryId" @click="openAdjustment()">库存调整</el-button></FactoryToolbar>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" @click="load">重试</el-button>
 <el-tabs v-model="tab" @tab-change="reset"><el-tab-pane label="原材料" name="RAW"/><el-tab-pane label="成品" name="PRODUCT"/><el-tab-pane label="半成品" name="SEMI"/></el-tabs>
 <el-table :data="rows" border v-loading="loading"><el-table-column v-for="c in columns" :key="c.key" :label="c.label" :min-width="c.width||130"><template #default="{row}">{{cell(row,c.key)}}</template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><el-button v-if="can('metal:inventory:query')" class="list-action list-action--primary list-action--row" @click="showDetail(row)">查看详情</el-button><el-button v-if="can('metal:inventory:adjust')" class="list-action list-action--edit list-action--row" @click="openAdjustment(row)">库存调整</el-button></template></el-table-column><template #empty>{{state.factoryId?'暂无库存':'请选择所属工厂'}}</template></el-table>
 <div class="storage-pagination"><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[16,32,64]" :total="total" layout="total,sizes,prev,pager,next,jumper" @change="load"/></div>
 <el-dialog v-model="detailOpen" title="库存详情" width="1050px" class="storage-dialog"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item v-for="c in columns" :key="c.key" :label="c.label">{{cell(detail,c.key)}}</el-descriptions-item></el-descriptions><el-table :data="detail.ownerships||[]" border><el-table-column prop="ownerName" label="料权方"/><el-table-column label="净重（g）"><template #default="{row}">{{decimalText(row.weight)}}</template></el-table-column><el-table-column prop="quantity" label="件数"/></el-table><h3>实物流水</h3><el-table :data="ledger.filter(row=>row.ledger==='PHYSICAL')" border class="physical-ledger"><el-table-column prop="documentNumber" label="关联单据"/><el-table-column label="类型"><template #default="{row}">{{ledgerActions[row.action]||row.action}}</template></el-table-column><el-table-column label="净重变动（g）"><template #default="{row}">{{decimalText(row.weightDelta)}}</template></el-table-column><el-table-column prop="quantityDelta" label="件数变动"/><el-table-column label="时间" min-width="170"><template #default="{row}">{{displayDateTime(row.createTime)}}</template></el-table-column></el-table></template></el-dialog>
 <OrderEditor ref="editor" @saved="load"/>
 <DebtPanel v-model="debtsOpen" @repay="repay"/>
</section>
</template>
<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue';import {onBeforeRouteLeave} from 'vue-router';import {ElMessage} from 'element-plus';import request from '@/utils/request'
import {displayDateTime} from '@/utils/display-date-time'
const ledgerActions:Record<string,string>={INBOUND:'入库',ISSUE:'生产领料',DISPATCH:'提料出库',RETURN:'原料退库',REPAYMENT:'料权归还',ADJUSTMENT:'库存调整',REVERSAL:'冲销'}
import FactoryToolbar from '../storage-live/FactoryToolbar.vue';import {useStorage,message,type Row} from '../storage-live/client';import {decimalText} from '@/utils/business-decimal';import {downloadCsv} from '../storage-preview/csv';import OrderEditor from '../storage-orders/OrderEditor.vue';import DebtPanel from '../storage-live/DebtPanel.vue'
const {state,can,context}=useStorage(),tab=ref('RAW'),page=ref(1),pageSize=ref(16),rows=ref<Row[]>([]),total=ref(0),loading=ref(false),error=ref(''),warehouses=ref<Row[]>([]),customers=ref<Row[]>([]),detailOpen=ref(false),detail=ref<Row>(),ledger=ref<Row[]>([]),debtsOpen=ref(false),editor=ref<InstanceType<typeof OrderEditor>>()
const blank=()=>({warehouseId:'',name:'',specification:'',customerId:''}),filters=ref(blank());let epoch=0,alive=true
const columns=computed(()=>[{key:'code',label:tab.value==='RAW'?'物料编码':'产品编码'},...(tab.value==='RAW'?[]:[{key:'name',label:'产品名称'}]),{key:tab.value==='RAW'?'materialType':'productType',label:tab.value==='RAW'?'物料类型名称':'产品类型'},...(tab.value==='RAW'?[{key:'materialCategory',label:'物料分类'},{key:'form',label:'物料形态'}]:[]),{key:'netWeight',label:'实物净重（g）'},{key:'quantity',label:'数量（件）'},{key:'specification',label:'规格型号'},{key:'metalType',label:'金属类型'},...(tab.value==='SEMI'?[{key:'processName',label:'加工阶段'}]:[]),{key:'batchNo',label:'批次号',width:200},{key:'warehouseName',label:'仓库'}])
function cell(row:Row,key:string){const value=row[key]??row.identity?.[key];if(key==='netWeight')return decimalText(value);if(key==='warehouseName')return warehouses.value.find(w=>w.id===row.warehouseId)?.name||value||'—';if(key==='form')return ({POWDER:'粉料',UNTREATED:'未处理料',METAL:'金属料'} as any)[value]||value||'—';return value??'—'}
async function load(){const id=++epoch,current=context();if(!state.factoryId){rows.value=[];total.value=0;return}loading.value=true;error.value='';try{const r:any=await request({url:'/metal/storage-inventory/list',params:{factoryId:state.factoryId,category:tab.value,...filters.value,pageNum:page.value,pageSize:pageSize.value},quiet:true});if(current===context()&&id===epoch&&alive){rows.value=r.rows||[];total.value=r.total||0}}catch(e){if(current===context()&&id===epoch)error.value=message(e)}finally{if(id===epoch)loading.value=false}}
async function loadOptions(){const current=context();if(!state.factoryId)return;try{const [w,c]:any[]=await Promise.all([request({url:'/metal/storage-warehouses/options',params:{factoryId:state.factoryId},quiet:true}),request({url:'/metal/options/customers',params:{factoryId:state.factoryId},quiet:true})]);if(current===context()){warehouses.value=w.data||[];customers.value=c.data||[]}}catch(e){if(current===context())error.value=message(e)}}
function search(){page.value=1;void load()}function reset(){filters.value=blank();page.value=1;detailOpen.value=false;void load()}
async function showDetail(row:Row){const current=context();try{const [d,l]:any[]=await Promise.all([request({url:`/metal/storage-inventory/${row.id}`,params:{factoryId:state.factoryId}}),request({url:`/metal/storage-inventory/${row.id}/ledger`,params:{factoryId:state.factoryId}})]);if(current===context()){detail.value=d.data;ledger.value=l.data||l.rows||[];detailOpen.value=true}}catch(e){error.value=message(e)}}
function openAdjustment(row?:Row){editor.value?.open('ADJUST',undefined,{type:'ADJUSTMENT',lines:row?[{stockId:row.id,warehouseId:row.warehouseId,ownerId:'0',deltaWeight:'',deltaQuantity:'',reason:''}]:[]})}
function repay(row:Row){debtsOpen.value=false;editor.value?.open('RETURN_RIGHTS',undefined,{type:'OWNERSHIP_RETURN',debt:row})}
async function exportRows(){const current=context(),all:Row[]=[];try{const r:any=await request({url:'/metal/storage-inventory/export',params:{factoryId:state.factoryId,category:tab.value,...filters.value}});if(current!==context())return;all.push(...r.data);downloadCsv('库存',columns.value.map(c=>c.label),all.map(r=>columns.value.map(c=>String(cell(r,c.key)))))}catch(e){ElMessage.error(message(e))}}
async function beforeChange(){return await editor.value?.requestClose()??true}
watch(()=>state.factoryId,()=>{epoch++;rows.value=[];warehouses.value=[];customers.value=[];detailOpen.value=false;debtsOpen.value=false;reset();void loadOptions()},{immediate:true});onBeforeRouteLeave(beforeChange);onBeforeUnmount(()=>{alive=false;epoch++})
</script>
<style scoped>.storage-inventory-page :deep(.storage-filter){flex-wrap:wrap}.storage-inventory-page :deep(.storage-filter .el-input),.storage-inventory-page :deep(.storage-filter .el-select){width:150px;flex:1 1 130px;min-width:100px}@media(min-width:1100px){.storage-inventory-page :deep(.storage-filter){flex-wrap:nowrap}}</style>
